//! App password and feed token resources.
//!
//! Secrets are generated by the server and shown exactly once, in the response that creates them; those responses
//! are `Cache-Control: no-store`. Revoking is idempotent. Creating operations accept an `Idempotency-Key`, but a
//! response that carries a secret is never stored and never replayed (PLAN 2.10): the repeat is answered
//! `secret-not-replayable` with the status and the `Location` of the first answer, so a client that lost it can find
//! the credential that was created and revoke it. The handlers only have to say `no_store`; the idempotency layer of
//! the edge keeps the secret out of its table, and stores nothing that a handler did not mark replayable.

use axum::extract::State;
use axum::http::StatusCode;
use davhaven_domain::{CredentialId, PrincipalName, TenantSlug, TokenId};
use davhaven_http::{Authenticated, EdgeProblem};
use davhaven_wire::{
    AppPasswordCreate, AppPasswordCreated, AppPasswordView, FeedTokenCreate, FeedTokenCreated, FeedTokenView, Page,
};
use utoipa_axum::router::OpenApiRouter;
use utoipa_axum::routes;

use crate::extract::{JsonBody, Keys, PageParams, Paging};
use crate::reply::Reply;
use crate::router::ApiState;

/// The routes of this module.
pub(crate) fn router() -> OpenApiRouter<ApiState> {
    OpenApiRouter::new()
        .routes(routes!(list_app_passwords, create_app_password))
        .routes(routes!(revoke_app_password))
        .routes(routes!(list_feed_tokens, create_feed_token))
        .routes(routes!(revoke_feed_token))
        .routes(routes!(rotate_feed_token))
}

/// Lists the app passwords of a principal, including revoked ones.
///
/// The listing shows labels, prefixes and state, never a secret.
#[utoipa::path(
    get,
    path = "/tenants/{tenant}/principals/{principal}/app-passwords",
    operation_id = "listAppPasswords",
    tag = "app-passwords",
    params(
        ("tenant" = String, Path, description = "The tenant slug."),
        ("principal" = String, Path, description = "The immutable name of the principal; for calendars and what belongs to them, the owner."),
        PageParams
    ),
    responses((status = 200, description = "A page of app passwords.", body = Page<AppPasswordView>))
)]
pub(crate) async fn list_app_passwords(
    State(state): State<ApiState>,
    Authenticated(ctx): Authenticated,
    Keys((_tenant, principal)): Keys<(TenantSlug, PrincipalName)>,
    paging: Paging,
) -> Result<Reply, EdgeProblem> {
    let page = state
        .services
        .credentials
        .list_app_passwords(&ctx, &principal, paging.request())
        .await?;
    Ok(paging.reply(&page))
}

/// Creates an app password for a DAV client.
///
/// The password is in the response and nowhere else; store it now.
#[utoipa::path(
    post,
    path = "/tenants/{tenant}/principals/{principal}/app-passwords",
    operation_id = "createAppPassword",
    tag = "app-passwords",
    params(
        ("tenant" = String, Path, description = "The tenant slug."),
        ("principal" = String, Path, description = "The immutable name of the principal; for calendars and what belongs to them, the owner.")
    ),
    request_body = AppPasswordCreate,
    responses((status = 201, description = "The app password, shown once.", body = AppPasswordCreated,
        headers(
            ("Location" = String, description = "The URL of the app password; `DELETE` it to revoke the password."),
            ("Cache-Control" = String, description = "`no-store`")
        ))
    )
)]
pub(crate) async fn create_app_password(
    State(state): State<ApiState>,
    Authenticated(ctx): Authenticated,
    Keys((tenant, principal)): Keys<(TenantSlug, PrincipalName)>,
    JsonBody(request): JsonBody<AppPasswordCreate>,
) -> Result<Reply, EdgeProblem> {
    let created = state
        .services
        .credentials
        .create_app_password(&ctx, &principal, request)
        .await?;
    let location = state.location(&format!(
        "tenants/{tenant}/principals/{principal}/app-passwords/{}",
        created.id
    ));
    let reply = Reply::json(StatusCode::CREATED, &created).no_store();
    Ok(match &location {
        Some(url) => reply.with_location(url),
        None => reply,
    })
}

/// Revokes an app password.
///
/// Revoking a revoked password changes nothing.
#[utoipa::path(
    delete,
    path = "/tenants/{tenant}/principals/{principal}/app-passwords/{id}",
    operation_id = "revokeAppPassword",
    tag = "app-passwords",
    params(
        ("tenant" = String, Path, description = "The tenant slug."),
        ("principal" = String, Path, description = "The immutable name of the principal; for calendars and what belongs to them, the owner."),
        ("id" = String, Path, description = "The id of the app password.")
    ),
    responses((status = 204, description = "The app password is revoked."))
)]
pub(crate) async fn revoke_app_password(
    State(state): State<ApiState>,
    Authenticated(ctx): Authenticated,
    Keys((_tenant, principal, id)): Keys<(TenantSlug, PrincipalName, CredentialId)>,
) -> Result<Reply, EdgeProblem> {
    state
        .services
        .credentials
        .revoke_app_password(&ctx, &principal, id)
        .await?;
    Ok(Reply::no_content())
}

