/// Creates a feed token for subscription feeds.
///
/// The feed URL contains the secret and is shown once. Answers 409 `feature-not-enabled` when the tenant disabled
/// feeds.
#[utoipa::path(
    post,
    path = "/tenants/{tenant}/principals/{principal}/feed-tokens",
    operation_id = "createFeedToken",
    tag = "feed-tokens",
    params(
        ("tenant" = String, Path, description = "The tenant slug."),
        ("principal" = String, Path, description = "The immutable name of the principal; for calendars and what belongs to them, the owner.")
    ),
    request_body = FeedTokenCreate,
    responses((status = 201, description = "The feed token and its URL, shown once.", body = FeedTokenCreated,
        headers(
            ("Location" = String, description = "The URL of the feed token; `DELETE` it to revoke the token."),
            ("Cache-Control" = String, description = "`no-store`")
        ))
    )
)]
pub(crate) async fn create_feed_token(
    State(state): State<ApiState>,
    Authenticated(ctx): Authenticated,
    Keys((tenant, principal)): Keys<(TenantSlug, PrincipalName)>,
    JsonBody(request): JsonBody<FeedTokenCreate>,
) -> Result<Reply, EdgeProblem> {
    let created = state
        .services
        .credentials
        .create_feed_token(&ctx, &principal, request)
        .await?;
    let location = state.location(&format!(
        "tenants/{tenant}/principals/{principal}/feed-tokens/{}",
        created.token.id
    ));
    let reply = Reply::json(StatusCode::CREATED, &created).no_store();
    Ok(match &location {
        Some(url) => reply.with_location(url),
        None => reply,
    })
}

