/// Replaces a feed token with a new secret for the same calendars.
///
/// The old URL stops working at once; the new one is shown once.
#[utoipa::path(
    post,
    path = "/tenants/{tenant}/principals/{principal}/feed-tokens/{id}/rotate",
    operation_id = "rotateFeedToken",
    tag = "feed-tokens",
    params(
        ("tenant" = String, Path, description = "The tenant slug."),
        ("principal" = String, Path, description = "The immutable name of the principal; for calendars and what belongs to them, the owner."),
        ("id" = String, Path, description = "The id of the feed token.")
    ),
    responses((status = 200, description = "The new feed token and its URL, shown once.", body = FeedTokenCreated,
        headers(("Cache-Control" = String, description = "`no-store`")))
    )
)]
pub(crate) async fn rotate_feed_token(
    State(state): State<ApiState>,
    Authenticated(ctx): Authenticated,
    Keys((_tenant, principal, id)): Keys<(TenantSlug, PrincipalName, TokenId)>,
) -> Result<Reply, EdgeProblem> {
    let rotated = state
        .services
        .credentials
        .rotate_feed_token(&ctx, &principal, id)
        .await?;
    Ok(Reply::json(StatusCode::OK, &rotated).no_store())
}
